std::optional<std::pair<size_t, geometry_msgs::msg::Point>> intersectLines(
  const std::vector<geometry_msgs::msg::Pose> & source_line,
  const std::vector<geometry_msgs::msg::Point> & target_line)
{
  for (int source_seg_idx = 0; source_seg_idx < static_cast<int>(source_line.size()) - 1;
       ++source_seg_idx) {
    for (int target_seg_idx = 0; target_seg_idx < static_cast<int>(target_line.size()) - 1;
         ++target_seg_idx) {
      const auto intersect_point = autoware_utils::intersect(
        source_line.at(source_seg_idx).position, source_line.at(source_seg_idx + 1).position,
        target_line.at(target_seg_idx), target_line.at(target_seg_idx + 1));
      if (intersect_point) {
        return std::make_pair(source_seg_idx, *intersect_point);
      }
    }
  }
  return std::nullopt;
}

std::optional<geometry_msgs::msg::Point> intersect(
  const geometry_msgs::msg::Point & p1, const geometry_msgs::msg::Point & p2,
  const geometry_msgs::msg::Point & p3, const geometry_msgs::msg::Point & p4)
{
  // Compute the determinant to check if the two lines are parallel.
  // If det is close to zero, the lines are nearly parallel and there's
  // no unique intersection point.
  const double det = (p1.x - p2.x) * (p4.y - p3.y) - (p4.x - p3.x) * (p1.y - p2.y);

  // A small tolerance factor for geometric computations.
  // Used to make the intersection detection more robust against
  // floating-point precision errors and to handle borderline cases consistently.
  constexpr double geometric_epsilon = 1e-9;

  if (std::abs(det) < geometric_epsilon) {
    // Lines are nearly parallel — treat this as no single intersection point.
    return std::nullopt;
  }

  const double t = ((p4.y - p3.y) * (p4.x - p2.x) + (p3.x - p4.x) * (p4.y - p2.y)) / det;
  const double s = ((p2.y - p1.y) * (p4.x - p2.x) + (p1.x - p2.x) * (p4.y - p2.y)) / det;

  // Helper function to check whether the intersection parameter is slightly
  // outside the [0, 1] range, considering a small tolerance margin.
  const auto is_outside_interval = [&](const double t) {
    return t < -geometric_epsilon || (1.0 + geometric_epsilon) < t;
  };

  // check collision is outside the segment line
  // Check if the computed intersection lies outside the segment boundaries.
  // The tolerance helps to avoid jitter or inconsistent results for
  // near-boundary cases caused by floating-point errors.
  if (is_outside_interval(t) || is_outside_interval(s)) {
    return std::nullopt;
  }

  geometry_msgs::msg::Point intersect_point;
  intersect_point.x = t * p1.x + (1.0 - t) * p2.x;
  intersect_point.y = t * p1.y + (1.0 - t) * p2.y;
  intersect_point.z = t * p1.z + (1.0 - t) * p2.z;
  return intersect_point;
}

double calcLateralOffset(
  const T & points, const geometry_msgs::msg::Point & p_target, const bool throw_exception = false)
{
  const auto overlap_removed_points = removeOverlapPoints(points, 0);

  if (throw_exception) {
    validateNonEmpty(overlap_removed_points);
  } else {
    try {
      validateNonEmpty(overlap_removed_points);
    } catch (const std::exception & e) {
      RCLCPP_DEBUG(
        get_logger(),
        "%s Return NaN since no_throw option is enabled. The maintainer must check the code.",
        e.what());
      return std::nan("");
    }
  }

  if (overlap_removed_points.size() == 1) {
    const std::string error_message(
      "[autoware_motion_utils] " + std::string(__func__) +
      ": Lateral offset calculation is not supported for the same points.");
    autoware_utils_system::print_backtrace();
    if (throw_exception) {
      throw std::runtime_error(error_message);
    }
    RCLCPP_DEBUG(
      get_logger(),
      "%s Return NaN since no_throw option is enabled. The maintainer must check the code.",
      error_message.c_str());
    return std::nan("");
  }

  const size_t seg_idx = findNearestSegmentIndex(overlap_removed_points, p_target);
  return calcLateralOffset(points, p_target, seg_idx, throw_exception);
}

[[nodiscard]] T removeOverlapPoints(const T & points, const size_t start_idx = 0)
{
  if (points.size() < start_idx + 1) {
    return points;
  }

  T dst;
  dst.reserve(points.size());

  for (size_t i = 0; i <= start_idx; ++i) {
    dst.push_back(points.at(i));
  }

  constexpr double eps = 1.0E-08;
  for (size_t i = start_idx + 1; i < points.size(); ++i) {
    const auto prev_p = autoware_utils_geometry::get_point(dst.back());
    const auto curr_p = autoware_utils_geometry::get_point(points.at(i));
    if (std::abs(prev_p.x - curr_p.x) < eps && std::abs(prev_p.y - curr_p.y) < eps) {
      continue;
    }
    dst.push_back(points.at(i));
  }

  return dst;
}

